CREATE TABLE IF NOT EXISTS repair_types(id BIGINT PRIMARY KEY AUTO_INCREMENT,type_name VARCHAR(50) UNIQUE,default_priority TINYINT NOT NULL,sla_hours INT NOT NULL);
INSERT IGNORE INTO repair_types(id,type_name,default_priority,sla_hours) VALUES (1,'电力',2,24),(2,'网络',2,24),(3,'桌椅',1,48);
CREATE TABLE IF NOT EXISTS repair_tickets(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_number VARCHAR(50) UNIQUE,reporter_id BIGINT NOT NULL,repair_type_id BIGINT NOT NULL,classroom_id BIGINT NULL,location_description VARCHAR(255) NOT NULL,description TEXT NOT NULL,priority TINYINT NOT NULL,status VARCHAR(30) NOT NULL,assigned_to BIGINT NULL,assigned_at DATETIME(3) NULL,deadline_at DATETIME(3) NOT NULL,escalation_count INT DEFAULT 0,completed_at DATETIME(3) NULL,accepted_at DATETIME(3) NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),revision INT NOT NULL DEFAULT 0,sync_pending BOOLEAN DEFAULT 0,maintenance_active BOOLEAN DEFAULT 0,INDEX(reporter_id),INDEX(status,deadline_at),FOREIGN KEY(repair_type_id) REFERENCES repair_types(id));
CREATE TABLE IF NOT EXISTS repair_progress(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL,operator_id BIGINT NULL,action_type VARCHAR(30) NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30),description TEXT,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(ticket_id) REFERENCES repair_tickets(id));
CREATE TABLE IF NOT EXISTS repair_reviews(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL UNIQUE,reviewer_id BIGINT NOT NULL,rating TINYINT NOT NULL,comment TEXT,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(ticket_id) REFERENCES repair_tickets(id));
CREATE TABLE IF NOT EXISTS event_outbox(id BIGINT PRIMARY KEY AUTO_INCREMENT,payload JSON NOT NULL,sent BOOLEAN NOT NULL DEFAULT 0);
